"""SQLModel models for items: one file for the table and the API shapes.

`Item` is the table. `ItemCreate`/`ItemUpdate` are the request bodies and share their
field definitions with the table through `ItemBase`, so a column and its validation
are declared once. These class names become the generated frontend type names.
"""

from datetime import UTC, datetime

from sqlalchemy import TIMESTAMP, BigInteger, Column, Identity, Integer
from sqlmodel import Field, SQLModel

# HANA wants BIGINT ... GENERATED BY DEFAULT AS IDENTITY; SQLite only autoincrements a
# column declared exactly INTEGER PRIMARY KEY, so it gets a variant.
_ID_TYPE = BigInteger().with_variant(Integer, "sqlite")


def _utcnow() -> datetime:
    # Naive UTC, matching what the database's own CURRENT_UTCTIMESTAMP would store
    return datetime.now(UTC).replace(tzinfo=None)


class ItemBase(SQLModel):
    name: str = Field(min_length=1, max_length=255)
    category: str = Field(default="General", min_length=1, max_length=100)
    description: str | None = Field(default=None, max_length=2000)
    quantity: int = Field(default=0, ge=0)


class Item(ItemBase, table=True):
    """The `items` table. Endpoints return `ItemPublic`, not this."""

    __tablename__ = "items"

    id: int | None = Field(
        default=None,
        sa_column=Column("id", _ID_TYPE, Identity(), primary_key=True),
    )
    category: str = Field(default="General", min_length=1, max_length=100, index=True)
    # TIMESTAMP, not DateTime: SQLAlchemy renders DateTime as DATETIME, which HANA rejects
    created_at: datetime = Field(default_factory=_utcnow, sa_type=TIMESTAMP, nullable=False)


class ItemCreate(ItemBase):
    pass


# Separate from `Item` so `id` and `created_at` are required in the API schema, while
# the table model leaves them unset before an insert. Docstrings here become the
# description in openapi.json, so keep them short.
class ItemPublic(ItemBase):
    """An item as returned by the API."""

    id: int
    created_at: datetime


class ItemUpdate(SQLModel):
    """Every field is optional; only the fields you send are changed."""

    name: str | None = Field(default=None, min_length=1, max_length=255)
    category: str | None = Field(default=None, min_length=1, max_length=100)
    description: str | None = Field(default=None, max_length=2000)
    quantity: int | None = Field(default=None, ge=0)


class CategoryTotal(SQLModel):
    """Aggregate row, not a table."""

    category: str
    total_quantity: int
    item_count: int
